export const BODY: string = "\n<p>تصویروں سے PDF بناتے وقت JPG اور PNG کا انتخاب PDF کا سائز، متن کی وضاحت اور پرنٹ کا معیار، تینوں بدل دیتا ہے۔ دونوں فارمیٹ PDF میں کام کرتے ہیں، مگر الگ طریقوں سے۔</p>\n<p>JPG چھوٹی PDF بناتا ہے اور تصویروں کے لیے بہترین ہے، جبکہ PNG متن کو تیز رکھتا ہے اور دستاویزات کے لیے بہتر ہے۔ غلط انتخاب یا تو فائل کو بہت بڑا کر دیتا ہے یا متن کو دھندلا کر دیتا ہے۔</p>\n<p>یہ مضمون دونوں فارمیٹوں کا PDF میں موازنہ کرتا ہے: فائل سائز، متن کی وضاحت، شفافیت، مخلوط بیچ اور عملی مثالیں۔ PDF بنانے کے لیے <a href=\"/ur/tasveer-se-pdf-banayein/\">امیج ٹو PDF</a> استعمال کریں۔</p>\n<h2 id=\"jpg-inside-pdf\">PDF کے اندر JPG تصویریں</h2>\n<p>JPG تصویریں PDF میں کمپریس ہو کر جاتی ہیں، اس لیے PDF چھوٹی رہتی ہے۔ فوٹو، پورٹریٹ اور مناظر JPG میں PDF کے لیے بہترین ہیں۔</p>\n<p>JPG کا نقصان یہ ہے کہ متن کے کنارے نرم ہو جاتے ہیں۔ اسکین شدہ دستاویز میں JPG متن کو دھندلا کر دیتا ہے، خاص طور پر کم معیار پر۔</p>\n<p>JPG PDF کے لیے اس وقت چنیں جب تصویر میں زیادہ تفصیل اور کم متن ہو۔ فوٹو البم اور پورٹ فولیو کے لیے JPG درست انتخاب ہے۔</p>\n<h2 id=\"png-inside-pdf\">PDF کے اندر PNG تصویریں</h2>\n<p>PNG تصویریں PDF میں بغیر نقصان کے جاتی ہیں، اس لیے متن اور لکیریں تیز رہتی ہیں۔ اسکین شدہ فارم، دستخط اور گرافکس PNG میں بہتر نکلتے ہیں۔</p>\n<p>PNG کا نقصان فائل سائز ہے: PNG تصویروں والی PDF JPG والی سے کئی گنا بڑی ہو سکتی ہے۔ فوٹو کے لیے PNG ضائع ہے، کیونکہ وہ بہت جگہ لیتا ہے۔</p>\n<p>PNG PDF کے لیے اس وقت چنیں جب متن پڑھنا سب سے اہم ہو۔ دستاویزات اور سرٹیفکیٹ کے لیے PNG درست انتخاب ہے۔</p>\n<h2 id=\"file-size-comparison\">فائل سائز: بڑا فرق</h2>\n<p>ایک ہی تصویر JPG میں 200KB اور PNG میں 2MB ہو سکتی ہے، اور یہ فرق PDF میں بھی آتا ہے۔ دس تصویروں کی PDF JPG میں 2MB اور PNG میں 20MB بن سکتی ہے۔</p>\n<p>بڑی PDF ای میل میں نہیں جاتی اور ڈاؤن لوڈ ہونے میں دیر لیتی ہے۔ اگر فائل سائز اہم ہو تو JPG چنیں، یا PNG تصویروں کو پہلے JPG میں بدلیں۔</p>\n<p>لیکن سائز کے لیے متن قربان نہ کریں: دھندلا متن والی چھوٹی PDF بیکار ہے۔ پہلے متن کی ضرورت دیکھیں، پھر سائز۔</p>\n<h2 id=\"text-sharpness\">متن کی وضاحت: جہاں PNG جیتتا ہے</h2>\n<p>PNG متن کے کناروں کو بالکل تیز رکھتا ہے، کیونکہ وہ بغیر نقصان کے محفوظ کرتا ہے۔ JPG متن کے گرد ہالہ بنا دیتا ہے، جو چھوٹے متن کو ناقابل خواندگی کر دیتا ہے۔</p>\n<p>فرق چھوٹے فونٹ میں سب سے زیادہ نظر آتا ہے۔ 10 پوائنٹ کا متن PNG میں صاف پڑھا جاتا ہے، جبکہ JPG میں وہ دھندلا لگتا ہے۔</p>\n<p>اگر دستاویز میں متن اہم ہو تو PNG چنیں، چاہے فائل بڑی ہو۔ پڑھنے کے قابل دستاویز ہی اصل مقصد ہے۔</p>\n<h2 id=\"photo-documents\">فوٹو دستاویزات: پورٹریٹ اور شناختی تصویریں</h2>\n<p>پورٹریٹ اور شناختی تصویریں JPG میں بہتر ہیں، کیونکہ ان میں نرم رنگ اور چہرے کی تفصیل ہوتی ہے۔ JPG ان رنگوں کو چھوٹی فائل میں اچھی طرح بچاتا ہے۔</p>\n<p>PNG میں پورٹریٹ بہت بڑا ہو جاتا ہے، بغیر کوئی فائدہ دیے۔ شناختی کارڈ کی PDF کے لیے JPG چنیں، تاکہ فائل ہلکی رہے۔</p>\n<p>شناختی تصویر میں چہرہ صاف ہونا چاہیے، اس لیے معیار 85 سے اوپر رکھیں۔ کم معیار پر چہرہ دھندلا ہو جاتا ہے اور شناخت مشکل ہو جاتی ہے۔</p>\n<h2 id=\"scanned-documents\">اسکین شدہ دستاویزات: معاہدے اور فارم</h2>\n<p>اسکین شدہ معاہدے اور فارم PNG میں بہتر ہیں، کیونکہ ان میں متن اور دستخط ہوتے ہیں۔ PNG دستخط کی باریک لکیریں تیز رکھتا ہے۔</p>\n<p>JPG میں اسکین شدہ دستاویز کا متن دھندلا ہو جاتا ہے، اور دستخط کی لکیریں ٹوٹ جاتی ہیں۔ قانونی دستاویز کے لیے یہ خطرناک ہے۔</p>\n<p>اگر اسکین شدہ دستاویز کی PDF بہت بڑی ہو تو اسے سرمئی رنگ میں بدلیں۔ سرمئی PNG رنگین سے چھوٹا ہوتا ہے اور متن اتنا ہی تیز رہتا ہے۔</p>\n<h2 id=\"transparency-handling\">شفافیت: اس کا کیا ہوتا ہے</h2>\n<p>PNG کی شفافیت PDF میں بچتی ہے، اور اس کے پیچھے صفحے کا سفید رنگ نظر آتا ہے۔ JPG میں شفافیت نہیں ہوتی، اس لیے اس کا پس منظر سفید بھر جاتا ہے۔</p>\n<p>لوگو یا دستخط کی شفاف تصویر PDF میں PNG کے طور پر رکھیں۔ JPG میں بدلنے سے شفاف حصہ سفید ہو جاتا ہے اور لوگو عجیب لگتا ہے۔</p>\n<p>پرنٹ میں شفافیت کا فرق نہیں پڑتا، کیونکہ کاغذ شفاف نہیں ہوتا۔ اسکرین پر دیکھنے کے لیے شفافیت اہم ہے، پرنٹ کے لیے نہیں۔</p>\n<h2 id=\"quality-settings\">ہر فارمیٹ کے لیے معیار کی سیٹنگز</h2>\n<p>JPG کے لیے معیار 85 سے 90 بہترین ہے: فائل ہلکی اور تصویر تیز۔ اس سے کم پر متن دھندلا ہو جاتا ہے، اس سے زیادہ پر فائل بہت بڑی ہو جاتی ہے۔</p>\n<p>PNG میں معیار کا سلائیڈر نہیں ہوتا، کیونکہ وہ بغیر نقصان کے محفوظ کرتا ہے۔ PNG کی فائل کم کرنے کے لیے اسے سرمئی کریں یا ابعاد چھوٹے کریں۔</p>\n<p>PDF بنانے سے پہلے ہر تصویر کا معیار جانچیں۔ ایک خراب تصویر پوری PDF کو خراب کر دیتی ہے۔</p>\n<h2 id=\"mixed-batches\">مخلوط بیچ: تصویریں اور اسکین ایک ساتھ</h2>\n<p>اکثر دستاویز میں تصویریں اور اسکین دونوں ہوتے ہیں، جیسے درخواست کے ساتھ فوٹو۔ اس صورت میں ہر تصویر کو اس کے اپنے فارمیٹ میں رکھیں: فوٹو JPG میں اور اسکین PNG میں۔</p>\n<p>مخلوط بیچ میں سب کو ایک فارمیٹ میں بدلنا غلطی ہے۔ سب کو JPG میں بدلنے سے متن خراب ہوتا ہے، اور سب کو PNG میں بدلنے سے فائل بہت بڑی ہو جاتی ہے۔</p>\n<p>ٹول ہر تصویر کا اپنا فارمیٹ برقرار رکھتا ہے، اس لیے مخلوط بیچ بنانا آسان ہے۔ بس تصویریں درست ترتیب میں لگائیں۔</p>\n<h2 id=\"which-to-choose\">کون سا فارمیٹ چنیں؟</h2>\n<p>اگر دستاویز میں زیادہ تصویریں ہوں تو JPG چنیں۔ اگر زیادہ متن ہو تو PNG چنیں۔ اگر دونوں ہوں تو مخلوط رکھیں۔</p>\n<p>فیصلہ کرنے سے پہلے دستاویز کا مقصد دیکھیں: ای میل کے لیے چھوٹی JPG PDF، پرنٹ کے لیے تیز PNG PDF، اور قانونی کام کے لیے PNG PDF بہترین ہے۔</p>\n<p>شک ہو تو دونوں نسخے بنا کر دیکھیں۔ ایک منٹ کا موازنہ غلط انتخاب سے بچاتا ہے۔</p>\n<h2 id=\"real-examples\">تین حقیقی مثالیں</h2>\n<p>پہلی مثال نوکری کی درخواست ہے: فوٹو JPG میں اور سرٹیفکیٹ PNG میں، جس سے PDF 3MB کی بنی اور متن صاف رہا۔</p>\n<p>دوسری مثال فوٹو البم ہے: سب تصویریں JPG میں، جس سے PDF 2MB کی بنی اور ہر تصویر تیز لگی۔ PNG میں یہی البم 20MB کا ہوتا۔</p>\n<p>تیسری مثال معاہدہ ہے: سب صفحے PNG میں، جس سے PDF 8MB کی بنی مگر دستخط اور متن بالکل تیز رہے۔ قانونی کام میں سائز سے زیادہ وضاحت اہم تھی۔</p>\n<h2 id=\"workflow-tips\">بہتر PDF کے لیے طریقہ کی تجاویز</h2>\n<p>پہلے تصویریں تیار کریں: فوٹو کو JPG میں کمپریس کریں اور اسکین کو PNG میں صاف کریں۔ پھر انہیں درست ترتیب میں لگائیں اور PDF بنائیں۔</p>\n<p>PDF بننے کے بعد اسے کھول کر ہر صفحہ دیکھیں۔ اگر کوئی صفحہ دھندلا ہو تو اس کی تصویر دوبارہ تیار کریں، پوری PDF دوبارہ نہ بنائیں۔</p>\n<p>PDF کا نام واضح رکھیں اور اس کا سائز جانچیں۔ اگر وہ ای میل کی حد سے باہر ہو تو معیار کم کریں۔</p>\n<h2 id=\"resolution-and-dpi\">PDF کے اندر ریزولوشن اور ڈی پی آئی</h2>\n<p>PDF میں تصویر کی ریزولوشن اس کے پکسلز سے طے ہوتی ہے۔ 300 ڈی پی آئی پر پرنٹ کے لیے تصویر کے ابعاد کافی بڑے ہونے چاہییں۔</p>\n<p>اسکرین پر دیکھنے کے لیے 150 ڈی پی آئی کافی ہے، مگر پرنٹ کے لیے 300 چاہیے۔ PDF بنانے سے پہلے ابعاد جانچیں، تاکہ پرنٹ دھندلا نہ نکلے۔</p>\n<p>ڈی پی آئی بدلنے سے پکسلز نہیں بدلتے، اس لیے پرنٹ کے لیے اصل بڑی تصویر استعمال کریں۔ چھوٹی تصویر کو بڑا کرنا حل نہیں۔</p>\n<h2 id=\"colour-rgb-grayscale\">رنگ: RGB بمقابلہ سرمئی صفحے</h2>\n<p>رنگین PDF اسکرین پر اچھی لگتی ہے، مگر پرنٹ میں مہنگی ہوتی ہے۔ سرمئی PDF چھوٹی ہوتی ہے اور پرنٹ میں سستی پڑتی ہے۔</p>\n<p>دستاویزات کے لیے سرمئی کافی ہے، کیونکہ متن سیاہ ہی ہوتا ہے۔ صرف اس وقت رنگین رکھیں جب تصویر کا رنگ اہم ہو، جیسے فوٹو یا چارٹ۔</p>\n<p>سرمئی کرنے سے PNG فائل بہت چھوٹی ہو جاتی ہے، بغیر متن کی وضاحت کم کیے۔ یہ دستاویزات کے لیے بہترین تجارت ہے۔</p>\n<h2 id=\"convert-photos-before\">بنانے سے پہلے تصویریں کب بدلیں</h2>\n<p>اگر تصویر کا فارمیٹ غلط ہو تو PDF بنانے سے پہلے اسے بدلیں۔ PNG فوٹو کو JPG میں بدلنے سے PDF بہت ہلکی ہو جاتی ہے۔</p>\n<p>اگر تصویر بہت بڑی ہو تو اسے پہلے ری سائز کریں۔ PDF میں بڑی تصویر ڈالنے سے فائل بھاری ہو جاتی ہے، بغیر کوئی فائدہ دیے۔</p>\n<p>تبدیلی کے لیے <a href=\"/ur/jpg-ko-png-mein-convert-karein/\">JPG ٹو PNG</a> یا <a href=\"/ur/png-ko-jpg-mein-convert-karein/\">PNG ٹو JPG</a> استعمال کریں، اور پھر PDF بنائیں۔</p>\n<h2 id=\"upload-portal-limits\">اپ لوڈ پورٹل پر فائل سائز کی حدیں</h2>\n<p>زیادہ تر پورٹل 2MB سے 10MB تک کی PDF لیتے ہیں۔ اس سے بڑی PDF مسترد ہو جاتی ہے، چاہے دستاویز درست ہو۔</p>\n<p>حد سے باہر ہونے پر پہلے JPG تصویروں کا معیار کم کریں، پھر PNG تصویروں کو سرمئی کریں۔ آخری حل تصویروں کی تعداد کم کرنا ہے۔</p>\n<p>اپ لوڈ سے پہلے PDF کا سائز جانچیں، تاکہ آخری وقت پر دوبارہ بنانا نہ پڑے۔</p>\n<h2 id=\"scanning-at-right-dpi\">درست ڈی پی آئی پر اسکین کرنا</h2>\n<p>دستاویز اسکین کرنے کے لیے 300 ڈی پی آئی کافی ہے: متن تیز اور فائل مناسب سائز کی بنتی ہے۔ اس سے کم پر متن دھندلا ہو جاتا ہے۔</p>\n<p>600 ڈی پی آئی صرف بہت باریک متن یا دستخط کے لیے چاہیے۔ عام دستاویز کے لیے 600 فائل کو دو گنا بڑا کر دیتا ہے، بغیر کوئی فائدہ دیے۔</p>\n<p>اسکین کرنے سے پہلے ڈی پی آئی طے کریں، کیونکہ بعد میں بڑھانا ممکن نہیں۔ درست ڈی پی آئی سے اسکین کرنا ہی بہترین طریقہ ہے۔ PDF بنانے کے عملی مراحل <a href=\"/ur/blog/tasveer-ko-pdf-mein-kaise-convert-karein/\">تصویر کو PDF میں کیسے بدلیں</a> اور مکمل رہنما <a href=\"/ur/blog/tasveer-se-pdf-rehnumai/\">امیج ٹو PDF رہنما</a> میں دیکھیں۔</p>\n";

